package com.inventra.backend.controller; import com.inventra.backend.dto.AlertResponse; import com.inventra.backend.service.AlertService; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/alerts") public class AlertController {private final AlertService s;public AlertController(AlertService s){this.s=s;}@GetMapping public List<AlertResponse> all(){return s.all();}@PostMapping("/refresh") public String refresh(){s.refresh();return "Alerts refreshed";}@PostMapping("/{id}/acknowledge") public AlertResponse acknowledge(@PathVariable String id){return s.acknowledge(id);}}
